-- User approved both table/column definitions for DEVELOPMENT on 2026-11-06.
-- Production application remains subject to separate release authorization.
CREATE TABLE cms_pages (
    page_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug VARCHAR(160) NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    title VARCHAR(200) NOT NULL CHECK (length(trim(title)) > 0),
    draft_content JSONB NOT NULL CHECK (jsonb_typeof(draft_content) = 'object'),
    published_content JSONB CHECK (published_content IS NULL OR jsonb_typeof(published_content) = 'object'),
    status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
    published_at TIMESTAMPTZ,
    created_by UUID REFERENCES users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES users(user_id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted BOOLEAN NOT NULL DEFAULT false,
    is_active BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT cms_pages_publication CHECK (status <> 'published' OR (published_content IS NOT NULL AND published_at IS NOT NULL))
);

CREATE TRIGGER trg_cms_pages_updated_at BEFORE UPDATE ON cms_pages
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE cms_page_revisions (
    revision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    page_id UUID NOT NULL REFERENCES cms_pages(page_id) ON DELETE CASCADE,
    version INTEGER NOT NULL CHECK (version > 0),
    content JSONB NOT NULL CHECK (jsonb_typeof(content) = 'object'),
    created_by UUID REFERENCES users(user_id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (page_id, version)
);

CREATE INDEX idx_cms_pages_public ON cms_pages (slug)
  WHERE status = 'published' AND is_active AND NOT is_deleted;

