INSERT INTO cms_pages(slug,title,draft_content,published_content,status,published_at) VALUES('about','About Us','{"schemaVersion":1,"seo":{"title":"About Jagdamba Travellers","description":"Why Jagdamba Travellers exists: chauffeur-driven trips across India with verified drivers and fully transparent fares."},"navigation":{"header":true,"footer":true,"label":"About","order":40},"sections":[{"id":"about-1","type":"text","visible":true,"appearance":{"background":"muted","imageUrl":"","overlay":50},"content":{"eyebrow":"About Us","title":"Travel across India, without the guesswork","subtitle":"","body":"Jagdamba Travellers started with a simple frustration: booking a reliable car with a good driver for an intercity trip in India was harder than it should be. Prices were opaque, vehicles were hit-or-miss, and you never knew who would show up.\n\nWe set out to fix that. Every Jagdamba Travellers trip is chauffeur-driven by a verified driver, in a maintained vehicle, at a fare you can see in full before you book — whether it''s a 20-minute airport run or a five-day Rajasthan tour.","items":[{"value":"500+","label":"Vehicles in the fleet"},{"value":"50K+","label":"Journeys completed"},{"value":"120+","label":"Cities covered"},{"value":"4.9/5","label":"Average trip rating"}]}},{"id":"about-2","type":"timeline","visible":true,"appearance":{"background":"default","imageUrl":"","overlay":50},"content":{"eyebrow":"Our Story","title":"How we got here","subtitle":"","items":[{"year":"2023","title":"The first ten cars","body":"Jagdamba Travellers launched in Mumbai with a small owned fleet and a promise: no self-drive, no surprises."},{"year":"2024","title":"Five ways to travel","body":"Point-to-point, hourly, outstation, airport transfer and multi-day packages — all through one transparent pricing engine."},{"year":"2025","title":"Build-your-own trips","body":"The Package Builder arrived, letting travellers design their own multi-stop routes on a map."},{"year":"2026","title":"12